import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec4 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-1-label';

  const pos = config.position || [0, 1, 0.06];
  const rot = config.rotation || [0, 0, 0];
  const scl = config.scale || [1, 1, 1];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  const atlasRegion = { x: 0, y: 0, w: 512, h: 320, atlasW: 512, atlasH: 320 };
  const aspect = atlasRegion.w / atlasRegion.h;
  const planeHeight = 0.34;
  const planeWidth = planeHeight * aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const grainTex = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  grainTex.colorSpace = THREE.SRGBColorSpace;

  const uOffset = atlasRegion.x / atlasRegion.atlasW;
  const vOffset = 1.0 - (atlasRegion.y + atlasRegion.h) / atlasRegion.atlasH;
  const uScale = atlasRegion.w / atlasRegion.atlasW;
  const vScale = atlasRegion.h / atlasRegion.atlasH;

  const atlasUV = uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));

  const material = new THREE.MeshBasicNodeMaterial();
  material.transparent = true;
  material.map = grainTex;
  material.colorNode = texture(grainTex, atlasUV);

  const bgMesh = new THREE.Mesh(geometry, material);
  bgMesh.name = 'pricing-card-1-label-bg';
  group.add(bgMesh);

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  let textMesh = null;
  if (ctx.fontAtlas && ctx.fontAtlas.createText) {
    textMesh = ctx.fontAtlas.createText({
      text: 'Pricing 2',
      font: 'Lora',
      weight: 400,
      size: 0.2,
      color: colors.paper,
      align: 'center',
      anchor: 'center'
    });
    textMesh.position.set(0, 0, 0.001);
    group.add(textMesh);
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (grainTex && grainTex.dispose) grainTex.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
  };

  return group;
}
